pageStyle:
.card-body {
    width: 960px;
    margin: auto;
    font-size: 16px;
}

h2 {
    color: #185468 !important;
    font-family: 'Barlow Condensed';
    font-style: normal;
    font-weight: 500;
    font-size: 34px;
    line-height: 1.5em;
}

.institution {
 width: 20%;
margin-right: 3%;
display: inline-block;
}

.institution img {
width: 100%;
}

.group {
margin-bottom: 30px;
clear: both;
}

.member {
margin-bottom: 50px;
clear: both;
}

.member img {
    width: 200px;
    float: left;
    margin-right: 20px;
    margin-bottom: 20px;
border: solid 1px #dddddd;
}

.member span.name {
    display: block;
    font-family: 'Barlow Condensed';
    font-style: normal;
    font-weight: 500;
    font-size: 28px;
    color: #185468 !important;
}

.member span.title {
    display: block;
    font-family: 'Barlow Condensed';
    font-style: normal;
    font-weight: 500;
    font-size: 18px;
}

.member span.description {
    display: block;
    margin-top: 15px
}
